// Extract and validate webhook data
const input = $input.first().json;
const body = input.body || input;

// Ensure we have all required fields
return [{
  json: {
    origin: body.origin || 'Hyderabad',
    destination: body.destination || 'Destination',
    start_date: body.start_date || new Date().toISOString().split('T')[0],
    end_date: body.end_date || new Date(Date.now() + 7*24*60*60*1000).toISOString().split('T')[0],
    passengers: body.passengers || 2,
    budget: body.budget || 'moderate'
  }
}];

// Build Groq API request with user data
const userData = $input.first().json;

const prompt = `Provide travel recommendations for a trip from ${userData.origin} to ${userData.destination} from ${userData.start_date} to ${userData.end_date} for ${userData.passengers} passenger(s).

Return a JSON object with this EXACT structure:
{
  "hotels": [
    {"name": "Hotel Name", "location": "Area", "price": "₹X,XXX/night", "duration": "N nights", "booking_link": "https://booking.com"},
    {"name": "Hotel 2", "location": "Area 2", "price": "₹X,XXX/night", "duration": "N nights", "booking_link": "https://booking.com"},
    {"name": "Hotel 3", "location": "Area 3", "price": "₹X,XXX/night", "duration": "N nights", "booking_link": "https://airbnb.com"}
  ],
  "trains": [
    {"name": "Train Name", "price": "₹XXX", "duration": "X hours", "booking_link": "https://irctc.co.in"}
  ],
  "buses": [
    {"name": "Bus Service", "price": "₹XXX", "duration": "X hours", "booking_link": "https://redbus.in"}
  ]
}

Provide 3 hotels, 1-2 trains, 1-2 buses. Use realistic prices for ${userData.destination}.`;

return [{
  json: {
    model: "llama-3.3-70b-versatile",
    messages: [
      {"role": "system", "content": "You are a travel assistant. Return ONLY valid JSON, no explanations."},
      {"role": "user", "content": prompt}
    ],
    response_format: {"type": "json_object"},
    temperature: 0.7
  }
}];

// Parse Groq response
try {
  const groqResponse = $input.first().json;
  if (groqResponse.choices && groqResponse.choices[0]) {
    const content = groqResponse.choices[0].message.content;
    const parsed = JSON.parse(content);
    return [{ json: parsed }];
  }
} catch (err) {
  console.error('Groq parse error:', err);
}

// Return empty on failure
return [{ json: { hotels: [], trains: [], buses: [] } }];

// Filter flights based on user criteria
const userData = $('Extract Parameters').first().json;
const flightData = $input.first().json;

const flights = flightData.data || [];
const filtered = [];

for (const flight of flights.slice(0, 50)) {
  try {
    const dep = flight.departure || {};
    const arr = flight.arrival || {};

    filtered.push({
      airline: flight.airline?.name || 'Unknown',
      flight_number: flight.flight?.iata || 'N/A',
      departure_airport: dep.airport || dep.iata || userData.origin,
      arrival_airport: arr.airport || arr.iata || userData.destination,
      departure_time: dep.scheduled || userData.start_date + 'T08:00:00',
      arrival_time: arr.scheduled || userData.start_date + 'T18:00:00',
      flight_date: flight.flight_date || userData.start_date,
      status: flight.flight_status || 'scheduled',
      price: '₹' + (8000 + Math.floor(Math.random() * 10000)).toLocaleString()
    });

    if (filtered.length >= 3) break;
  } catch (err) {
    continue;
  }
}

return [{ json: { data: filtered } }];

// Combine all results and add fallback if needed
const userData = $('Extract Parameters').first().json;

const result = {
  flights: [],
  hotels: [],
  trains: [],
  buses: [],
  metadata: {
    origin: userData.origin,
    destination: userData.destination,
    start_date: userData.start_date,
    end_date: userData.end_date,
    passengers: userData.passengers
  },
  fallback_used: false
};

// Collect data from all input items
for (const item of $input.all()) {
  const json = item.json;

  if (json.data && Array.isArray(json.data)) {
    result.flights = json.data;
  }
  if (json.hotels && Array.isArray(json.hotels)) {
    result.hotels = json.hotels;
  }
  if (json.trains && Array.isArray(json.trains)) {
    result.trains = json.trains;
  }
  if (json.buses && Array.isArray(json.buses)) {
    result.buses = json.buses;
  }
}

// Calculate nights
const nights = Math.ceil((new Date(userData.end_date) - new Date(userData.start_date)) / (1000*60*60*24));

// Add fallback data if everything is empty
const allEmpty = result.flights.length === 0 && result.hotels.length === 0;

if (allEmpty) {
  result.fallback_used = true;

  result.flights = [
    {
      airline: 'IndiGo',
      flight_number: '6E-' + Math.floor(Math.random() * 1000),
      departure_airport: userData.origin,
      arrival_airport: userData.destination,
      departure_time: userData.start_date + 'T08:00:00',
      arrival_time: userData.start_date + 'T18:00:00',
      flight_date: userData.start_date,
      status: 'scheduled',
      price: '₹12,500'
    },
    {
      airline: 'Air India',
      flight_number: 'AI-' + Math.floor(Math.random() * 1000),
      departure_airport: userData.origin,
      arrival_airport: userData.destination,
      departure_time: userData.start_date + 'T14:00:00',
      arrival_time: userData.start_date + 'T23:30:00',
      flight_date: userData.start_date,
      status: 'scheduled',
      price: '₹10,800'
    }
  ];

  result.hotels = [
    {
      name: userData.destination + ' Beach Resort',
      location: userData.destination + ' - Beachfront',
      price: '₹8,500/night',
      duration: nights + ' nights',
      booking_link: 'https://booking.com'
    },
    {
      name: userData.destination + ' City Hotel',
      location: userData.destination + ' - City Center',
      price: '₹6,200/night',
      duration: nights + ' nights',
      booking_link: 'https://booking.com'
    },
    {
      name: userData.destination + ' Luxury Villa',
      location: userData.destination + ' - Premium',
      price: '₹12,000/night',
      duration: nights + ' nights',
      booking_link: 'https://airbnb.com'
    }
  ];

  result.trains = [
    {
      name: 'Express Train to ' + userData.destination,
      price: '₹1,500',
      duration: '8 hours',
      booking_link: 'https://irctc.co.in'
    }
  ];

  result.buses = [
    {
      name: 'Luxury Bus to ' + userData.destination,
      price: '₹800',
      duration: '10 hours',
      booking_link: 'https://redbus.in'
    }
  ];
}

return [{ json: result }];
